import hashlib,json,pathlib,sys
base=pathlib.Path(sys.argv[1]); result={}
for folder in (base/"phase_probe",base/"libraries"):
 for path in sorted(folder.rglob("*")):
  if path.is_symlink(): raise SystemExit("Unexpected fixture symlink")
  if path.is_file(): result[str(path)]=hashlib.sha256(path.read_bytes()).hexdigest()
print(json.dumps(result))
